-- ==================================================================
-- Nexora Seed: 120 Stocks Across 6 Markets (20 Stocks Each)
-- Self-contained DDL and clean data for TiDB Cloud
-- ==================================================================
USE `nexora`;

-- 0. Ensure AI discovery tables exist
CREATE TABLE IF NOT EXISTS `instruments` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `symbol` varchar(20) NOT NULL,
  `exchange` varchar(20) NOT NULL DEFAULT 'NEXORA',
  `company_name` varchar(150) NOT NULL,
  `sector` varchar(50) DEFAULT NULL,
  `industry` varchar(80) NOT NULL,
  `description` longtext,
  `current_price` decimal(12,2) DEFAULT NULL,
  `market_cap` decimal(18,2) DEFAULT NULL,
  `instrument_status` enum('ACTIVE','SUSPENDED','DELISTED') NOT NULL DEFAULT 'ACTIVE',
  `data_as_of` date DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UK_instrument_symbol` (`symbol`)
);

CREATE TABLE IF NOT EXISTS `market_data_snapshots` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `instrument_id` bigint NOT NULL,
  `metric_key` varchar(50) NOT NULL,
  `metric_value` decimal(14,4) DEFAULT NULL,
  `unit` varchar(20) DEFAULT NULL,
  `currency` varchar(10) DEFAULT 'INR',
  `source` varchar(100) DEFAULT NULL,
  `as_of` date DEFAULT NULL,
  `retrieved_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `FK_snapshot_instrument` (`instrument_id`),
  CONSTRAINT `FK_snapshot_instrument` FOREIGN KEY (`instrument_id`) REFERENCES `instruments` (`id`) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS `watchlist_items` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `instrument_id` bigint NOT NULL,
  `notes` varchar(255) DEFAULT NULL,
  `added_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UK_user_instrument` (`user_id`,`instrument_id`)
);

CREATE TABLE IF NOT EXISTS `user_investment_preferences` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `risk_preference` enum('LOWER','MODERATE','HIGHER') NOT NULL,
  `investment_horizon` enum('SHORT_TERM','MEDIUM_TERM','LONG_TERM') NOT NULL,
  `portfolio_source` enum('WALLET_AND_HOLDINGS','MANUAL','NONE') NOT NULL,
  `target_industries` text,
  `updated_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UK_user_preference` (`user_id`)
);

CREATE TABLE IF NOT EXISTS `analysis_runs` (
  `id` varchar(36) NOT NULL,
  `user_id` bigint NOT NULL,
  `run_status` enum('PENDING','COMPLETED','FAILED') NOT NULL,
  `status_message` varchar(255) DEFAULT NULL,
  `risk_preference` varchar(30) DEFAULT NULL,
  `investment_horizon` varchar(30) DEFAULT NULL,
  `industries_analyzed` text,
  `candidates_evaluated_count` int DEFAULT 0,
  `recommendations_returned_count` int DEFAULT 0,
  `created_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`)
);

CREATE TABLE IF NOT EXISTS `recommendation_results` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `analysis_run_id` varchar(36) NOT NULL,
  `instrument_id` bigint NOT NULL,
  `rank_order` int NOT NULL,
  `score` int NOT NULL,
  `score_category` varchar(50) DEFAULT NULL,
  `quality_score` int DEFAULT NULL,
  `valuation_score` int DEFAULT NULL,
  `growth_score` int DEFAULT NULL,
  `risk_score` int DEFAULT NULL,
  `industry_fit_score` int DEFAULT NULL,
  `portfolio_fit_score` int DEFAULT NULL,
  `plain_summary` text,
  `why_it_matches` text,
  `risks_to_consider` text,
  `portfolio_impact` text,
  `data_limitations` text,
  `disclaimer` text,
  `created_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`)
);

-- 1. Clean up legacy external non-Nexora instruments
DELETE FROM `recommendation_results` WHERE `instrument_id` IN (SELECT `id` FROM `instruments` WHERE `exchange` != 'NEXORA');
DELETE FROM `watchlist_items` WHERE `instrument_id` IN (SELECT `id` FROM `instruments` WHERE `exchange` != 'NEXORA');
DELETE FROM `market_data_snapshots` WHERE `instrument_id` IN (SELECT `id` FROM `instruments` WHERE `exchange` != 'NEXORA');
DELETE FROM `instruments` WHERE `exchange` != 'NEXORA';


